import {groupsAt,roundBrief,boundsForHole,atlasPosition,clock,situation} from './play-model.js';
import {bandon} from './bandon-data.js';
import {createCourseMap} from './course-map.js';
import {courses,loadCourse,routePosition} from './course-registry.js';
const $=s=>document.querySelector(s),L=window.L;
let course=courses[0],courseData=null,courseLayer=null,loadSequence=0,lines=new Map();
let minute=0,hole=1,selected=8,choice='auto',started=false,ended=false,running=false,follow=true,mode='atlas',timer,lastState='normal',lastHole=1,geo=null,atlas=null,toastTimer,events=[];
const flightPins=new Map();
const groupMarkers=new Map(),holeImages=new Map(),holeButtons=new Map(),rows=new Map();
function notify(text){$('#toast').textContent=text;$('#toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').hidden=true,4000);}
function addEvent(message){events.unshift({message,time:clock(510+minute)});events=events.slice(0,5);$('#updates').replaceChildren(...events.map(e=>{const el=document.createElement('div');el.className='update';const text=document.createElement('span'),time=document.createElement('small');text.textContent=e.message;time.textContent=e.time+' · simulated';el.append(text,time);return el;}));$('#update-count').textContent=events.length;}
function ensureHole(h){return courseData?.holes.find(x=>x.hole===h);}
function getGroups(){return groupsAt(minute*245/course.target,choice);}
function mediaPath(kind,h){const n=String(h).padStart(2,'0');return `assets/${course.id}/${kind}-${n}${kind==='flight'?'.mp4':'.jpg'}`;}
function setFlight(){const v=$('#traffic-film');v.pause();$('#flight-groups').hidden=!course.media;if(course.media){const src=mediaPath('flight',hole);if(v.getAttribute('src')!==src){v.setAttribute('src',src);v.poster=mediaPath(course.id==='bandon'?'hole':'flight',hole);v.load();}$('#no-flight').hidden=true;v.hidden=false;}else{v.removeAttribute('src');v.load();v.hidden=true;$('#no-flight').hidden=false;}$('#flight-hole').textContent=`${course.name} · Hole ${hole}`;}
async function switchCourse(id){const sequence=++loadSequence;pause();geo?.stopGPS();$('#map-loading').hidden=false;$('#map-loading').textContent='Opening course…';try{const data=await loadCourse(id);if(sequence!==loadSequence)return;course=courses.find(c=>c.id===id);courseData=data;minute=0;hole=1;selected=8;started=false;ended=false;choice='auto';lastState='normal';lastHole=1;events=[];$('#scenario').value='auto';$('#updates').replaceChildren();$('#update-count').textContent='0';$('#course-search').value=course.name;$('#course-region').textContent=course.region.toUpperCase()+' · 4 DEMO COURSES';document.title=course.name+' · Fairway Flow traffic';if(globalThis.location&&globalThis.history){const url=new URL(location.href);url.searchParams.set('course',course.id);history.replaceState({},'',url);}for(const m of groupMarkers.values())m.remove();groupMarkers.clear();lines.clear();courseLayer?.remove();courseLayer=L.layerGroup().addTo(atlas);const colors={fairway:'#8aa774',green:'#b2ca80',tee:'#98b57c',bunker:'#e2d4ab',sand:'#ded0a6',water:'#7da7a1',wood:'#81966d',forest:'#81966d',rough:'#a8b78a'};for(const f of data.terrain)L.polygon(f.points,{stroke:false,fillColor:colors[f.kind]||'#b9c49f',fillOpacity:f.kind==='wood'||f.kind==='forest'?.5:.95,interactive:false}).addTo(courseLayer);for(const h of data.holes){const line=L.polyline(h.route,{color:'#faf4d4',weight:3,opacity:.7}).on('click',()=>{setFollow(false);selectHole(h.hole);}).addTo(courseLayer);lines.set(h.hole,line);L.marker(h.route.at(-1),{icon:L.divIcon({className:'',html:`<button class="route-hole" aria-label="Explore hole ${h.hole}">${h.hole}</button>`,iconSize:[24,24],iconAnchor:[12,12]})}).on('click',()=>{setFollow(false);selectHole(h.hole);}).addTo(courseLayer);}atlas.fitBounds(data.bounds,{paddingTopLeft:[40,150],paddingBottomRight:[40,150]});geo?.setCourse({id:course.id,center:data.holes[0].route[0]});setFollow(false);selectHole(1,{camera:false});update();$('#map-loading').hidden=true;}catch(e){$('#map-loading').textContent=e.message+' · reload to retry';}}

function selectHole(h,{camera=true}={}){hole=Math.max(1,Math.min(18,h));if(camera&&atlas&&mode==='atlas'){const selectedRoute=ensureHole(hole);if(selectedRoute)atlas.fitBounds(selectedRoute.route,{paddingTopLeft:[55,130],paddingBottomRight:[55,145],animate:!matchMedia('(prefers-reduced-motion: reduce)').matches,maxZoom:18});}for(const [h,b] of holeButtons)b.setAttribute('aria-pressed',String(h===hole));$('#hole-title').textContent=`Hole ${String(hole).padStart(2,'0')} · Par ${ensureHole(hole)?.par??'—'}`;$('#traffic-title').textContent=`Hole ${String(hole).padStart(2,'0')} traffic`;$('#flyover-link').href=course.media?`course-preview.html?course=${course.id}&hole=${hole}`:`round-review.html`;for(const [id,line] of lines)line.setStyle({color:id===hole?'#f1d189':'#faf4d4',weight:id===hole?6:3,opacity:id===hole?1:.65});if(mode==='flight')setFlight();$('#prev').disabled=hole===1;$('#next').disabled=hole===18;updateDetails();}
function setFollow(value){follow=value;$('#follow').classList.toggle('active',follow);$('#follow').textContent=follow?'◎ Following my group':'◎ Follow my group';}
function updateDetails(){const groups=getGroups();for(const g of groups){const row=rows.get(g.id);row.element.hidden=g.hole!==hole;row.element.classList.toggle('active',selected===g.id);row.detail.textContent=g.stale?'Last demo observation · stale':`${Math.round(g.fraction*100)}% of demo hole`;row.stage.textContent=g.id===8?'You':'View →';}const sel=groups.find(g=>g.id===selected);$('#selection-detail').textContent=`Selected: Group ${String(selected).padStart(2,'0')} · hole ${sel.hole}. ${sel.stale?'Tracking interruption: its marker is frozen.':'Illustrative position on hole artwork, not measured GPS.'}`;}
function update(){const groups=getGroups(),own=groups.find(g=>g.id===8),brief=roundBrief(minute*245/course.target,choice);brief.finish=clock(510+course.target+(brief.state==='queue'?18:brief.state==='gap'?10:0));for(const g of groups){if(!atlas)continue;ensureHole(g.hole);const route=ensureHole(g.hole);if(!route)continue;const pos=routePosition(route.route,g.fraction);let marker=groupMarkers.get(g.id);if(!marker){marker=L.marker(pos,{icon:L.divIcon({className:'',html:`<div class="group-pin ${g.id===8?'you':''}">${String(g.id).padStart(2,'0')}</div>`,iconSize:[35,35],iconAnchor:[17,17]})}).on('click',()=>{selected=g.id;setFollow(false);selectHole(getGroups().find(x=>x.id===g.id).hole,{camera:false});notify(`Group ${String(g.id).padStart(2,'0')} selected. Open round details for its status.`);}).addTo(atlas);groupMarkers.set(g.id,marker);}else marker.setLatLng(pos);const el=marker.getElement()?.firstElementChild;if(el){el.classList.toggle('selected',selected===g.id);el.classList.toggle('stale',g.stale);}}
 if(follow&&running&&mode==='atlas'){if(own.hole!==hole)selectHole(own.hole);else atlas?.panTo(routePosition(ensureHole(own.hole).route,own.fraction),{animate:false});}
 $('#brief-title').textContent=started?brief.title:'A clearer picture of the course.';$('#brief-message').textContent=started?brief.message:'Start a round to watch your group and the traffic ahead change over time.';$('#own-hole').innerHTML=String(own.hole).padStart(2,'0')+' <small>/ 18</small>';$('#finish').textContent=brief.finish;$('#demo-time').textContent=clock(510+minute)+' · simulated';$('#timeline-label').textContent=Math.floor(minute)+' simulated minutes';$('#timeline').max=course.target;if(document.activeElement!==$('#timeline'))$('#timeline').value=Math.floor(minute);$('#round-state').textContent=ended?'ROUND ENDED':running?'IN PROGRESS':started?'PAUSED':'NOT STARTED';$('#live-badge').innerHTML='<i></i> '+(running?'DEMO RUNNING':started?'DEMO PAUSED':'DEMO READY');$('#pause').disabled=!started||ended;$('#pause').textContent=running?'Ⅱ Pause':'▷ Resume';$('#end').disabled=!started||ended;$('#start-card').hidden=started||mode!=='atlas';updateDetails();updateFlight();
 if(started&&brief.state!==lastState){addEvent(brief.message);notify(brief.message);lastState=brief.state;}if(started&&own.hole!==lastHole){addEvent(`Your group entered hole ${own.hole}.`);lastHole=own.hole;}}
function pause(){running=false;clearInterval(timer);}
function run(){if(ended)return;running=true;clearInterval(timer);timer=setInterval(()=>{minute=Math.min(course.target,minute+Number($('#speed').value)*.25);update();if(minute>=course.target)endRound();},250);update();}
function startRound(){started=true;ended=false;selected=8;setFollow(true);selectHole(getGroups().find(g=>g.id===8).hole);addEvent('Your round started. Group 08 is sharing a simulated position.');run();notify('You’re on the course. Tap a group, drag the map, or follow your round.');}
function endRound(){pause();ended=true;geo?.stopGPS();addEvent('Round ended. The $5 credit is a demo concept; no money was issued.');update();notify('Demo round finished. Reset in Demo controls to try again.');}
for(let h=1;h<=18;h++){const b=document.createElement('button');b.textContent=String(h).padStart(2,'0');b.setAttribute('aria-label','Explore hole '+h);b.onclick=()=>{setFollow(false);selectHole(h);};$('#hole-picker').append(b);holeButtons.set(h,b);}
for(let id=4;id<=11;id++){const element=document.createElement('button');element.className='group-row';const badge=document.createElement('b'),label=document.createElement('span'),name=document.createElement('span'),detail=document.createElement('small'),stage=document.createElement('span');badge.textContent=String(id).padStart(2,'0');name.textContent=id===8?'Your group':'Group '+String(id).padStart(2,'0');label.append(name,detail);element.append(badge,label,stage);element.onclick=()=>{selected=id;setFollow(false);selectHole(getGroups().find(g=>g.id===id).hole);update();};rows.set(id,{element,detail,stage});$('#group-list').append(element);}
if(L){atlas=L.map('atlas',{minZoom:12,maxZoom:20,zoomSnap:.25,attributionControl:true,preferCanvas:true}).setView([43.187,-124.391],15);atlas.attributionControl.setPrefix('<a href="https://leafletjs.com">Leaflet</a>');atlas.attributionControl.addAttribution('&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap contributors</a> · ODbL');atlas.on('dragstart',()=>setFollow(false));}else $('#map-loading').textContent='The map library could not load. Please reload this page.';
$('#start').onclick=startRound;$('#pause').onclick=()=>{if(running){pause();update();}else run();};$('#end').onclick=endRound;$('#overview').onclick=()=>{if(mode==='geo'){geo?.overview();return;}setFollow(false);atlas?.fitBounds(courseData.bounds,{paddingTopLeft:[35,90],paddingBottomRight:[35,130]});};$('#follow').onclick=()=>{if(mode==='geo')return;selected=8;setFollow(true);selectHole(getGroups().find(g=>g.id===8).hole);update();};$('#prev').onclick=()=>{setFollow(false);selectHole(hole-1);};$('#next').onclick=()=>{setFollow(false);selectHole(hole+1);};
document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{mode=b.dataset.mode;$('#atlas').hidden=mode!=='atlas';$('#geographic').hidden=mode!=='geo';$('#flyover-board').hidden=mode!=='flight';if(mode!=='flight')$('#traffic-film').pause();else setFlight();$('#location').hidden=mode!=='geo';$('#follow').hidden=mode==='geo';$('#start-card').hidden=started||mode!=='atlas';document.querySelectorAll('[data-mode]').forEach(x=>x.setAttribute('aria-selected',String(x===b)));$('#map-caption').textContent=mode==='geo'?'REAL GEOGRAPHIC MAP · OPTIONAL DEVICE GPS · NO SHARED GROUP FEED':mode==='flight'?'COURSE FOOTAGE · APPROXIMATE DEMO OVERLAYS, NOT CAMERA-TRACKED GPS':'OPENSTREETMAP COURSE ROUTES · SIMULATED GROUPS · COMMUNITY DATA, NOT SURVEYED GPS';$('#map-help').querySelector('strong').textContent=mode==='geo'?'Your real location.':mode==='flight'?'Explore the hole.':'Explore the course.';$('#map-help').querySelector('span').textContent=mode==='geo'?'Enable GPS to see your device. Demo groups appear on the course traffic map.':'Pan, zoom, or tap a group. Your simulation continues while you explore.';if(mode==='geo'&&!geo&&L){geo=createCourseMap($('#geographic'),{L,onStatus:text=>{if(mode==='geo')$('#map-help').querySelector('span').textContent=text;notify(text);}});geo.setCourse({id:course.id,center:courseData.holes[0].route[0]});}requestAnimationFrame(()=>{if(mode==='geo')geo?.resize();else atlas?.invalidateSize();});});
$('#location').onclick=()=>{if(!window.isSecureContext){notify('GPS requires HTTPS or localhost.');return;}geo?.startGPS();};$('#settings').onclick=()=>{const open=$('#controls').hidden;$('#controls').hidden=!open;$('#settings').setAttribute('aria-expanded',String(open));};$('#close-controls').onclick=()=>{$('#controls').hidden=true;$('#settings').setAttribute('aria-expanded','false');};$('#scenario').onchange=e=>{choice=e.target.value;update();};$('#timeline').oninput=e=>{minute=+e.target.value;update();};$('#reset').onclick=()=>{pause();geo?.stopGPS();minute=0;selected=8;started=false;ended=false;choice='auto';events=[];lastState='normal';lastHole=1;$('#scenario').value='auto';$('#updates').replaceChildren();$('#update-count').textContent='0';$('#start-card').hidden=mode!=='atlas';setFollow(true);selectHole(1);update();};$('#sheet-toggle').onclick=()=>{const open=document.body.classList.toggle('sheet-open');$('#sheet-toggle').setAttribute('aria-expanded',String(open));$('#sheet-toggle').textContent=open?'Close round details ↓':'Your round & traffic ↑';};window.addEventListener('pagehide',()=>{pause();geo?.stopGPS();});if(L){const requested=new URLSearchParams(globalThis.location?.search||'').get('course');switchCourse(courses.some(c=>c.id===requested)?requested:'bandon');}

function updateFlight(){if(!courseData)return;const current=getGroups().filter(g=>g.hole===hole);const host=$('#flight-groups');for(const g of getGroups()){let b=flightPins.get(g.id);if(!b){b=document.createElement('button');b.className='flight-group'+(g.id===8?' you':'');b.textContent='Group '+String(g.id).padStart(2,'0');b.onclick=()=>{selected=g.id;updateDetails();notify('Selected demo group '+g.id);};host.append(b);flightPins.set(g.id,b);}b.hidden=g.hole!==hole;b.classList.toggle('stale',g.stale);b.style.left=(22+g.fraction*52)+'%';b.style.top=(72-g.fraction*48)+'%';}$('#flight-population').textContent=current.length+' demo groups on this hole · approximate overlay, not camera-tracked GPS';}

$('#traffic-film').onloadedmetadata=()=>{$('#flight-scrub').disabled=false;};$('#traffic-film').onerror=()=>{$('#flight-population').textContent='This footage could not load. The course map remains available.';};$('#flight-scrub').oninput=e=>{const v=$('#traffic-film');if(Number.isFinite(v.duration)){v.pause();v.currentTime=+e.target.value/100*v.duration;}};
$('#course-options').replaceChildren(...courses.map(c=>{const o=document.createElement('option');o.value=c.name;return o;}));$('#course-search').onchange=e=>{const c=courses.find(c=>c.name.toLowerCase()===e.target.value.trim().toLowerCase());if(c)switchCourse(c.id);else notify('Choose one of the four courses in the demo library.');};
